					adorn->setObjectToWorldMatrix(G3D::CoordinateFrame(position));
					adorn->sphere(G3D::Sphere(G3D::Vector3::zero(), 0.5f), G3D::Color3::red(), G3D::Color4::clear());
				}
			}
		}
	}
